const MONOGRAM = "data:image/png;base64,";
const SPRING = "cubic-bezier(0.22, 1, 0.36, 1)";
const GOLD = "#C89B4B";
const INK = "#1C1B22";

/* ================= hooks ================= */

function useInView(threshold = 0.22) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setInView(true);
          io.disconnect();
        }
      },
      { threshold }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [threshold]);
  return [ref, inView];
}

function useCountdown(target) {
  const calc = () => {
    const diff = Math.max(0, target - Date.now());
    return {
      days: Math.floor(diff / 864e5),
      hours: Math.floor((diff % 864e5) / 36e5),
      mins: Math.floor((diff % 36e5) / 6e4),
      secs: Math.floor((diff % 6e4) / 1e3),
    };
  };
  const [t, setT] = useState(calc);
  useEffect(() => {
    const id = setInterval(() => setT(calc), 1000);
    return () => clearInterval(id);
  }, []);
  return t;
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const fn = (e) => setReduced(e.matches);
    mq.addEventListener("change", fn);
    return () => mq.removeEventListener("change", fn);
  }, []);
  return reduced;
}

/* ================= ambient background ================= */

/* Gold dust + drifting petals on a full-page canvas */
function AmbientCanvas({ active }) {
  const canvasRef = useRef(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    if (reduced || !active) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    let W, H, raf;
    const DPR = Math.min(window.devicePixelRatio || 1, 2);

    const resize = () => {
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * DPR;
      canvas.height = H * DPR;
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    };
    resize();
    window.addEventListener("resize", resize);

    const N = Math.min(46, Math.floor(W / 26));
    const parts = Array.from({ length: N }, () => spawn(true));

    function spawn(anywhere) {
      const petal = Math.random() < 0.28;
      return {
        x: Math.random() * W,
        y: anywhere ? Math.random() * H : H + 20,
        r: petal ? 4 + Math.random() * 5 : 0.8 + Math.random() * 1.8,
        petal,
        vy: -(0.12 + Math.random() * 0.3),
        vx: (Math.random() - 0.5) * 0.15,
        sway: Math.random() * Math.PI * 2,
        swaySpeed: 0.004 + Math.random() * 0.008,
        rot: Math.random() * Math.PI * 2,
        rotSpeed: (Math.random() - 0.5) * 0.01,
        alpha: 0.14 + Math.random() * 0.3,
      };
    }

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      for (let p of parts) {
        p.sway += p.swaySpeed;
        p.x += p.vx + Math.sin(p.sway) * 0.25;
        p.y += p.vy;
        p.rot += p.rotSpeed;
        if (p.y < -30 || p.x < -30 || p.x > W + 30) Object.assign(p, spawn(false));

        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.translate(p.x, p.y);
        if (p.petal) {
          ctx.rotate(p.rot);
          ctx.fillStyle = GOLD;
          ctx.beginPath();
          ctx.ellipse(0, 0, p.r, p.r * 0.45, 0, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillStyle = GOLD;
          ctx.beginPath();
          ctx.arc(0, 0, p.r, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }
      raf = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
    };
  }, [reduced, active]);

  if (reduced) return null;
  return (
    <canvas
      ref={canvasRef}
      style={{ position: "fixed", inset: 0, pointerEvents: "none", zIndex: 1 }}
      aria-hidden="true"
    />
  );
}

/* Huge faint script watermarks + flourishes that parallax with scroll */
function Watermarks() {
  const [scrollY, setScrollY] = useState(0);
  const reduced = usePrefersReducedMotion();
  useEffect(() => {
    if (reduced) return;
    let raf;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => setScrollY(window.scrollY));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(raf);
    };
  }, [reduced]);

  const mark = (top, left, right, size, char, speed, rot = 0) => (
    <div
      style={{
        position: "absolute",
        top,
        left,
        right,
        fontFamily: "'Playfair Display', serif",
        fontStyle: "italic",
        fontSize: size,
        color: INK,
        opacity: 0.032,
        transform: `translateY(${reduced ? 0 : scrollY * speed}px) rotate(${rot}deg)`,
        userSelect: "none",
        lineHeight: 1,
        whiteSpace: "nowrap",
      }}
      aria-hidden="true"
    >
      {char}
    </div>
  );

  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", zIndex: 0, pointerEvents: "none" }}>
      {mark("6%", "-4%", "auto", "clamp(240px,42vw,520px)", "N", -0.06, -8)}
      {mark("26%", "auto", "-6%", "clamp(240px,42vw,520px)", "S", -0.1, 10)}
      {mark("48%", "-2%", "auto", "clamp(200px,34vw,420px)", "love", -0.05, -14)}
      {mark("68%", "auto", "-4%", "clamp(240px,40vw,500px)", "&", -0.09, 6)}
      {mark("88%", "6%", "auto", "clamp(180px,30vw,380px)", "forever", -0.04, -10)}
    </div>
  );
}

/* ================= animated primitives ================= */

function Rise({ children, delay = 0, y = 36, duration = 1.4, style = {}, as: Tag = "div" }) {
  const [ref, inView] = useInView();
  return (
    <Tag
      ref={ref}
      style={{
        opacity: inView ? 1 : 0,
        transform: inView ? "translateY(0)" : `translateY(${y}px)`,
        transition: `opacity ${duration}s ${SPRING} ${delay}s, transform ${duration}s ${SPRING} ${delay}s`,
        willChange: "opacity, transform",
        ...style,
      }}
    >
      {children}
    </Tag>
  );
}

function InkReveal({ children, delay = 0 }) {
  const [ref, inView] = useInView();
  return (
    <span
      ref={ref}
      style={{
        display: "inline-block",
        clipPath: inView ? "inset(-20% -5% -30% -5%)" : "inset(-20% 105% -30% -5%)",
        opacity: inView ? 1 : 0,
        transition: `clip-path 2.2s ${SPRING} ${delay}s, opacity .6s ease ${delay}s`,
      }}
    >
      {children}
    </span>
  );
}

function GrowRule({ delay = 0, vertical = false, style = {} }) {
  const [ref, inView] = useInView();
  return (
    <div
      ref={ref}
      aria-hidden="true"
      style={{
        background: vertical
          ? `linear-gradient(180deg, transparent, ${GOLD}, transparent)`
          : `linear-gradient(90deg, transparent, ${GOLD}, transparent)`,
        transform: inView ? "scale(1)" : vertical ? "scaleY(0)" : "scaleX(0)",
        transition: `transform 1.8s ${SPRING} ${delay}s`,
        ...style,
      }}
    />
  );
}

function Digit({ value, label }) {
  const [display, setDisplay] = useState(value);
  const [pop, setPop] = useState(false);
  const [hover, setHover] = useState(false);
  useEffect(() => {
    if (value !== display) {
      setPop(true);
      const t = setTimeout(() => {
        setDisplay(value);
        setPop(false);
      }, 160);
      return () => clearTimeout(t);
    }
  }, [value, display]);
  return (
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        textAlign: "center",
        minWidth: "clamp(58px, 14vw, 96px)",
        transform: hover ? "translateY(-6px)" : "translateY(0)",
        transition: `transform .5s ${SPRING}`,
        cursor: "default",
      }}
    >
      <div
        style={{
          fontFamily: "'Cinzel', serif",
          fontSize: "clamp(44px, 9vw, 72px)",
          lineHeight: 1,
          color: INK,
          fontVariantNumeric: "tabular-nums",
          opacity: pop ? 0 : 1,
          transform: pop ? "translateY(-10px)" : "translateY(0)",
          transition: `opacity .16s ease, transform .3s ${SPRING}`,
        }}
      >
        {display}
      </div>
      <div
        style={{
          marginTop: 16,
          height: 1,
          margin: "16px auto 14px",
          width: hover ? 44 : 0,
          background: GOLD,
          transition: `width .5s ${SPRING}`,
        }}
      />
      <div
        style={{
          fontFamily: "'Cormorant Garamond', serif",
          fontSize: 11,
          letterSpacing: "0.4em",
          textIndent: "0.4em",
          textTransform: "uppercase",
          color: GOLD,
        }}
      >
        {label}
      </div>
    </div>
  );
}

